CREATE POLICY approved_parent_only ON public.ppo_operacional_itens AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT public.has_role(auth.uid(),'dp') OR public.is_admin_or_higher(auth.uid()) OR EXISTS(SELECT 1 FROM public.ppo_operacional_avaliacoes WHERE id=ppo_id AND status='aprovado'));
CREATE POLICY approved_parent_only ON public.ppo_avaliacao_itens AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT public.has_role(auth.uid(),'dp') OR public.is_admin_or_higher(auth.uid()) OR EXISTS(SELECT 1 FROM public.ppo_avaliacoes WHERE id=avaliacao_id AND status IN ('aguardando_validacao','validada','comunicada','em_contestacao','encerrada')));
CREATE POLICY dp_operacional_no_insert ON public.ppo_operacional_avaliacoes AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(NOT public.has_role(auth.uid(),'dp') OR public.is_admin_or_higher(auth.uid()));
DO $$ DECLARE t text; BEGIN FOR t IN SELECT unnest(ARRAY['ppo_ciclos','ppo_indicadores','ppo_pesos_pilar','ppo_faixas_indicador','ppo_sla','ppo_governanca','ppo_ocorrencias','ppo_feedbacks','ppo_contestacoes','ppo_termos_ciencia','ppo_auditoria_log','ppo_plano_acao','ppo_barreiras','ppo_melhorias','ppo_cargos','ppo_setores']) LOOP EXECUTE format('CREATE POLICY module_access ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING(public.can_access_module(auth.uid(),''ppo'')) WITH CHECK(public.can_access_module(auth.uid(),''ppo''))',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.guard_approved_trip() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_higher(auth.uid()) AND OLD.status='aprovado' AND NOT public.is_gestor_or_higher(auth.uid()) THEN RAISE EXCEPTION 'Apontamento aprovado: solicite devolução ao gestor'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_approved_trip BEFORE UPDATE OR DELETE ON public.ppo_motoristas_turnos FOR EACH ROW EXECUTE FUNCTION public.guard_approved_trip();